y":255,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":400},"Jan. 1"],["rect",{"x":535,"y":190.0,"width":52,"height":44.0,"fill":"#1A3560","rx":0},null],["text",{"x":561,"y":255,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":400},"Jan. 15"],["line",{"x1":69,"y1":102,"x2":630,"y2":102,"stroke":"#4A5568","stroke-width":1.3,"stroke-dasharray":"5 4"},null],["text",{"x":625,"y":95,"fill":"#4A5568","text-anchor":"end","font-size":13,"font-weight":400},"$240 reserve"],["rect",{"x":201,"y":35,"width":44,"height":16,"fill":"#E8A825","rx":7},null],["text",{"x":223.0,"y":47,"fill":"#242628","text-anchor":"middle","font-size":11,"font-weight":700},"$320"],["rect",{"x":111,"y":272,"width":10,"height":10,"fill":"#1A3560","rx":0},null],["text",{"x":129,"y":282,"fill":"#4A5568","text-anchor":"start","font-size":13,"font-weight":400},"New purchases"],["rect",{"x":292,"y":272,"width":10,"height":10,"fill":"#8A3030","rx":0},null],["text",{"x":310,"y":282,"fill":"#4A5568","text-anchor":"start","font-size":13,"font-weight":400},"Previously scheduled"]].forEach(function(row){
