":423,"y2":156,"stroke":"#1A3560","stroke-width":2,"stroke-dasharray":""},null],["circle",{"cx":423,"cy":156,"r":5,"fill":"#1A3560"},null],["text",{"x":433,"y":147,"fill":"#4A5568","text-anchor":"start","font-size":13,"font-weight":400},"$8,000"],["text",{"x":207,"y":214,"fill":"#4A5568","text-anchor":"end","font-size":13,"font-weight":400},"January opening"],["line",{"x1":223,"y1":209,"x2":423,"y2":209,"stroke":"#1A3560","stroke-width":2,"stroke-dasharray":""},null],["circle",{"cx":423,"cy":209,"r":5,"fill":"#1A3560"},null],["text",{"x":433,"y":200,"fill":"#4A5568","text-anchor":"start","font-size":13,"font-weight":400},"$8,000"],["rect",{"x":553,"y":30,"width":65,"height":16,"fill":"#E8A825","rx":7},null],["text",{"x":585.5,"y":42,"fill":"#242628","text-anchor":"middle","font-size":11,"font-weight":700},"$16,000"],["text",{"x":427,"y":286,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":400},"2027 room available"]].forEach(function(row){
