  svg.setAttribute(''width'',''100%'');
  svg.setAttribute(''role'',''img'');
  svg.setAttribute(''aria-label'',"How Quebec changed the national total");
  svg.setAttribute(''font-family'',''system-ui, sans-serif'');
  [["rect",{"x":0,"y":0,"width":680,"height":300,"fill":"#FFFFFF","rx":0},null],["line",{"x1":66,"y1":232,"x2":621,"y2":232,"stroke":"#D0D0D0","stroke-width":1,"stroke-dasharray":""},null],["text",{"x":55,"y":236,"fill":"#4A5568","text-anchor":"end","font-size":13,"font-weight":400},"0"],["line",{"x1":66,"y1":202,"x2":621,"y2":202,"stroke":"#D0D0D0","stroke-width":1,"stroke-dasharray":""},null],["text",{"x":55,"y":206,"fill":"#4A5568","text-anchor":"end","font-size":13,"font-weight":400},"5"],["line",{"x1":66,"y1":172,"x2":621,"y2":172,"stroke":"#D0D0D0","stroke-width":1,"stroke-dasharray":""},null],["text",{"x":55,"y":176,"fill":"#4A5568","text-anchor":"end","font-size":13,"font-weight":400},"10"],["line",{"x1":66,"y1":142,"x2":621,"y2":142,"stroke":"#D0D0D0","stroke-width":1,"stroke-dasharray":""},null],["text",{"x":55,"y":146,"fill":"#4A5568","text-anchor":"end","font-size":13,"font-weight":400},"15"],["line",{"x1":66,"y1":112,"x2":621,"y2":112,"stroke":"#D0D0D0","stroke-width":1,"stroke-dasharray":""},null],["text",{"x":55,"y":116,"fill":"#4A5568","text-anchor":"end","font-size":13,"font-weight":400},"20"],["line",{"x1":66,"y1":82,"x2":621,"y2":82,"stroke":"#D0D0D0","stroke-width":1,"stroke-dasharray":""},null],["text",{"x":55,"y":86,"fill":"#4A5568","text-anchor":"end","font-size":13,"font-weight":400},"25"],["line",{"x1":66,"y1":52,"x2":621,"y2":52,"stroke":"#D0D0D0","stroke-width":1,"stroke-dasharray":""},null],["text",{"x":55,"y":56,"fill":"#4A5568","text-anchor":"end","font-size":13,"font-weight":400},"30"],["rect",{"x":130,"y":72.142,"width":79,"height":159.858,"fill":"#397955","rx":0},null],["text",{"x":169.5,"y":257,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":400},"Rest of Canada"],["text",{"x":169.5,"y":64.142,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":600},"+$26.64M"],["rect",{"x":300,"y":72.142,"width":79,"height":73.09800000000001,"fill":"#8A3030","rx":0},null],["text",{"x":339.5,"y":257,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":400},"Quebec"],["rect",{"x":304,"y":50.141999999999996,"width":72,"height":16,"fill":"#E8A825","rx":7},null],["text",{"x":340.0,"y":62.141999999999996,"fill":"#242628","text-anchor":"middle","font-size":11,"font-weight":700},"−$12.18M"],["rect",{"x":470,"y":145.24,"width":79,"height":86.75999999999999,"fill":"#1A3560","rx":0},null],["text",{"x":509.5,"y":257,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":400},"Canada"],["text",{"x":509.5,"y":137.24,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":600},"+$14.46M"],["line",{"x1":209,"y1":72.142,"x2":300,"y2":72.142,"stroke":"#4A5568","stroke-width":1,"stroke-dasharray":"4 3"},null],["line",{"x1":379,"y1":145.24,"x2":470,"y2":145.24,"stroke":"#4A5568","stroke-width":1,"stroke-dasharray":"4 3"},null],["text",{"x":343,"y":281,"fill":"#4A5568","text-anchor":"middle","font-size":13,"font-weight":400},"Change in monthly sales"]].forEach(function(row){
    var node=document.createElementNS(ns,row[0]);
    Object.keys(row[1]).forEach(function(key){node.setAttribute(key,row[1][key]);});
    if(row[2]!==null){node.textContent=row[2];}
    svg.appendChild(node);
  });
  mount.parentNode.appendChild(svg);
